function apiUrl(path){const [route,query]=path.split('?');return 'api.php?route='+encodeURIComponent(route)+(query?'&'+query:'')}
const $=s=>document.querySelector(s),app=$('#app');let user,activePeriod=null,classes=[],page='Dashboard',current,tab='Absensi',meeting=1,changes=new Map(),masterData,masterTab='mahasiswa';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>v===null||v===undefined?'—':Number(v).toFixed(1);const roleLabel={admin:'Admin Laboratorium',asisten:'Asisten',dosen:'Dosen Pengampu',mahasiswa:'Mahasiswa'};
async function api(path,data,method){const r=await fetch(apiUrl(path),{method:method||(data?'POST':'GET'),headers:data?{'Content-Type':'application/json','X-CSRF-Token':user?.csrf||''}:{},body:data?JSON.stringify(data):undefined});const b=r.status===204?null:await r.json();if(!r.ok){if(r.status===401&&path!='/login')login();throw Error(b?.error||'Permintaan API ditolak.')}return b}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4500)}
function badge(s){return `<span class="badge ${['Dikunci','Terverifikasi','Lengkap'].includes(s)?'green':s==='Perlu Revisi'?'red':['Diajukan','Draft'].includes(s)?'yellow':''}">${esc(s)}</span>`}
function brand(){return '<div class="brand"><img class="brand-logo" src="assets/logo-iclabs.jpg" alt="Logo ICLabs" width="54" height="57"><div><strong>ICLabs Praktikum</strong><small>FIKOM UMI</small></div></div>'}
function login(){
  user=null;
  app.innerHTML=`<main class="iclabs-login"><section class="login-panel" aria-labelledby="login-title">
    <div class="login-heading"><img src="assets/logo-iclabs.jpg" class="login-logo" alt="Logo ICLabs" width="94" height="100"><h1 id="login-title">ICLabs Praktikum</h1><p>Integrated Computer Laboratory System</p></div>
    <form id="login">
      <label for="login-email">Email atau username</label><div class="login-input"><svg class="input-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/></svg><input id="login-email" name="email" type="text" placeholder="Masukkan email atau username" autocomplete="username" required></div>
      <label for="login-password">Password</label><div class="login-input"><svg class="input-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="5" y="10" width="14" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/></svg><input id="login-password" name="password" type="password" placeholder="Masukkan password" autocomplete="current-password" required><button type="button" id="toggle-password" aria-label="Tampilkan password" aria-pressed="false"><svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div>
      <label class="login-remember"><input id="remember-email" type="checkbox">Ingat email di perangkat ini</label>
      <div id="login-error" role="alert"></div><button class="login-submit" type="submit">↪ Masuk</button>
    </form><p class="login-copyright">© ${new Date().getFullYear()} ICLabs — Hak cipta dilindungi</p>
  </section></main>`;
  try{const remembered=localStorage.getItem('iclabs-login-email');if(remembered){$('#login-email').value=remembered;$('#remember-email').checked=true}}catch{}
  $('#remember-email').onchange=()=>{if(!$('#remember-email').checked){try{localStorage.removeItem('iclabs-login-email')}catch{}}};
  $('#toggle-password').onclick=()=>{const field=$('#login-password'),show=field.type==='password';field.type=show?'text':'password';$('#toggle-password').setAttribute('aria-pressed',String(show));$('#toggle-password').setAttribute('aria-label',show?'Sembunyikan password':'Tampilkan password')};
  $('#login').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]'),values=Object.fromEntries(new FormData(form));button.disabled=true;button.textContent='Memproses…';$('#login-error').textContent='';try{await api('/login',values);try{if($('#remember-email').checked)localStorage.setItem('iclabs-login-email',values.email);else localStorage.removeItem('iclabs-login-email')}catch{}await init()}catch(x){$('#login-error').textContent=x.message}finally{button.disabled=false;button.textContent='↪ Masuk'}};
}
async function init(){try{user=await api('/me');activePeriod=await api('/active-period');classes=user.role==='mahasiswa'?[]:await api('/classes');current=null;changes.clear();page=user.api_mode?(user.role==='mahasiswa'?'Nilai Saya':'Ringkasan'):(user.role==='mahasiswa'?'Nilai Saya':'Dashboard');render()}catch(e){if(!user){login();if(e.message&&e.message!=='Silakan login.'&&$('#login-error'))$('#login-error').textContent=e.message;return}app.innerHTML=`<main class="iclabs-login"><section class="login-panel"><div class="login-heading"><img src="assets/logo-iclabs.jpg" class="login-logo" alt="Logo ICLabs" width="94" height="100"><h1>ICLabs Praktikum</h1><p>Integrasi API sedang disiapkan</p></div><div class="error" role="alert">${esc(e.message||'Fitur belum tersedia melalui API pusat.')}</div><button class="login-submit" onclick="init()">Coba lagi</button><button class="small" style="margin-top:12px" onclick="logout()">Keluar</button></section></main>`}}
const icons={'Nilai Saya':'▧','Dashboard':'▦','Jadwal Praktikum':'▤','Absensi':'☑','Penilaian':'▧','Verifikasi':'◈','Laporan':'▥','Data Master':'⚙','Konfigurasi Nilai':'%','Log Aktivitas':'◷'};
function render(){if(user?.api_mode){renderApiMode();return}const nav=user.role==='mahasiswa'?['Nilai Saya']:Object.keys(icons).filter(x=>x!=='Nilai Saya'&&(user.role==='admin'||!['Data Master','Log Aktivitas'].includes(x)));app.innerHTML=`<div class="app"><aside class="sidebar">${brand()}<div class="navlabel">MENU UTAMA</div><nav class="nav">${nav.map(x=>`<button data-nav="${x}" class="${page===x?'active':''}"><span class="icon">${icons[x]}</span>${x}</button>`).join('')}</nav><div class="sidebar-footer"><div class="labcard"><strong>Laboratorium FIKOM UMI</strong>Ruang belajar, bereksperimen,<br>dan bertumbuh bersama.<br><span class="badge green" style="margin-top:12px">● Sistem aktif</span></div><button id="logout" style="margin-top:15px;width:100%;font-size:12px">↪ Keluar dari akun</button></div></aside><div class="content"><header class="topbar"><div class="row"><button class="mobile" id="menu">☰</button><div><strong>ICLabs Praktikum</strong><small>Fakultas Ilmu Komputer – Universitas Muslim Indonesia</small></div></div><div class="profile"><div class="avatar">${esc(user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><button id="account" aria-label="Akun dan ganti password"><span class="profile-name"><strong>${esc(user.name)}</strong><small>${roleLabel[user.role]}⌄</small></span></button><button id="header-logout" class="logout-button" aria-label="Logout dari akun">↪ Logout</button></div></header><main class="workspace"><div id="period-summary">${periodSummary()}</div><div id="view"></div></main></div></div>`;
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));$('#logout').onclick=logout;$('#header-logout').onclick=logout;$('#account').onclick=account;$('.profile .avatar').onclick=account;$('#menu').onclick=()=>$('.sidebar').classList.toggle('open');if(user.role==='mahasiswa')studentPortal();else if(current)renderClass();else if(page==='Dashboard')dashboard();else if(page==='Data Master')masters();else if(page==='Log Aktivitas')auditPage();else listPage()}
function renderApiMode(){
  const student=user.role==='mahasiswa',nav=student?['Nilai Saya']:(user.role==='admin'?['Ringkasan','Kelas Praktikum','Konfigurasi Nilai','Log Aktivitas']:['Ringkasan','Kelas Praktikum']);
  const initials=(user.name||user.email||'IC').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
  app.innerHTML=`<div class="app"><aside class="sidebar">${brand()}<div class="navlabel">MENU UTAMA</div><nav class="nav">${nav.map(x=>`<button data-api-nav="${x}" class="${page===x?'active':''}"><span class="icon">${icons[x]||'▦'}</span>${x}</button>`).join('')}</nav><div class="sidebar-footer"><div class="labcard"><strong>Data terpusat ICLabs</strong>Informasi dibaca langsung dari API pusat.<br><span class="badge green" style="margin-top:12px">● Mode API</span></div><button id="api-logout" style="margin-top:15px;width:100%;font-size:12px">↪ Keluar dari akun</button></div></aside><div class="content"><header class="topbar"><div class="row"><button class="mobile" id="api-menu">☰</button><div><strong>ICLabs Praktikum</strong><small>Fakultas Ilmu Komputer – Universitas Muslim Indonesia</small></div></div><div class="profile"><div class="avatar">${esc(initials)}</div><button id="api-account" aria-label="Akun dan ganti password"><span class="profile-name"><strong>${esc(user.name)}</strong><small>${roleLabel[user.role]} · API pusat</small></span></button><button id="api-header-logout" class="logout-button" aria-label="Logout dari akun">↪ Logout</button></div></header><main class="workspace"><div id="api-period-summary">${apiPeriodSummary()}</div><div id="api-view"></div></main></div></div>`;
  document.querySelectorAll('[data-api-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.apiNav;apiCurrent=null;renderApiMode()});$('#api-logout').onclick=logout;$('#api-header-logout').onclick=logout;$('#api-account').onclick=account;$('#api-menu').onclick=()=>$('.sidebar').classList.toggle('open');
  if(student)apiStudentGrades();else if(apiCurrent)apiClassDetailWithEntry(apiCurrent);else if(page==='Kelas Praktikum')apiClassList();else if(page==='Konfigurasi Nilai')gradeConfigPage();else if(page==='Log Aktivitas')auditPage();else apiDashboard();
}
function apiPeriodSummary(){const p=activePeriod;return `<section class="period-summary" aria-label="Periode akademik pusat"><div><small>Periode aktif pusat</small><strong>${p?esc(p.academic_year)+' · '+esc(p.semester):'Belum ada periode aktif'}</strong></div><div><small>Tanggal pelaksanaan</small><strong>${p?esc(p.start_date||'—')+' – '+esc(p.end_date||'—'):'—'}</strong></div></section>`}
async function apiDashboard(){const view=$('#api-view');view.innerHTML='<div class="empty">Memuat ringkasan dari API pusat…</div>';try{const d=await api('/dashboard'),percent=value=>value===null?'—':`${Number(value).toFixed(1)}%`;view.innerHTML=`<div class="intro"><div class="eyebrow">RUANG KERJA / RINGKASAN</div><h1>Ringkasan Praktikum</h1><p>Statistik dihitung oleh API pusat dari kelas yang memang dapat Anda akses.</p></div><div class="stats">${[[d.jumlah_kelas,'Kelas Praktikum','▦','Periode dan penugasan yang dapat diakses'],[d.jumlah_peserta_aktif,'Peserta aktif','♙','Jumlah pendaftaran pada kelas'],[d.pertemuan_tercatat,'Pertemuan tercatat','☑',`${Number(d.pertemuan_direncanakan||0)} direncanakan`],[d.jadwal_perlu_perhatian,'Perlu perhatian','◈','Jadwal diajukan atau perlu revisi']].map(([n,label,icon,note])=>`<div class="stat"><div class="row between"><span class="label">${esc(label)}</span><span class="stat-icon">${icon}</span></div><b>${Number(n||0)}</b><small>${esc(note)}</small></div>`).join('')}</div><section class="card"><div class="card-head"><h2>Progres pengisian</h2><p>Rekap atas presensi dan nilai yang tersimpan pada API pusat.</p></div><div class="card-body"><div class="api-progress-row"><span>Presensi</span><strong>${Number(d.presensi_terisi||0)} / ${Number(d.presensi_diharapkan||0)}</strong><span>${percent(d.persentase_presensi)}</span></div><div class="api-progress-row"><span>Nilai komponen</span><strong>${Number(d.nilai_terisi||0)} / ${Number(d.nilai_diharapkan||0)}</strong><span>${percent(d.persentase_nilai)}</span></div></div><div class="card-body"><button class="primary" id="api-open-classes">Buka daftar kelas</button></div></section>`;$('#api-open-classes').onclick=()=>{page='Kelas Praktikum';apiCurrent=null;renderApiMode()}}catch(error){view.innerHTML=`<div class="error" role="alert">${esc(error.message)}</div>`}}
let apiCurrent=null;
function apiStatus(v){return String(v||'—').replace(/_/g,' ').toLowerCase().replace(/\b\w/g,c=>c.toUpperCase())}
async function apiClassList(){const view=$('#api-view');view.innerHTML='<div class="empty">Memuat kelas dari API pusat…</div>';try{const result=await api('/classes');if(!Array.isArray(result))throw Error('Format daftar kelas tidak valid.');classes=result;view.innerHTML=`<div class="intro"><div class="eyebrow">RUANG KERJA / DATA API PUSAT</div><h1>Kelas Praktikum</h1><p>Data kelas dan kelompok dibaca dari database integrasi ICLabs.</p></div><section class="card"><div class="card-head row between"><div><h2>Daftar kelas</h2><p>${classes.length} kelas dapat diakses oleh akun Anda.</p></div>${user.role==='admin'?'<div class="row"><button class="small" id="api-import-schedule">↑ Import jadwal</button><button class="primary" id="api-create-class">+ Tambah kelas</button></div>':''}</div>${classes.map(c=>`<button class="api-class-row" data-api-class="${Number(c.id_kelas_kuliah)}"><span><strong>${esc(c.mata_kuliah.kode)} · ${esc(c.mata_kuliah.nama)}</strong><small>${esc(c.program_studi.nama)} · Kelompok ${esc(c.kelompok.kode)} · ${esc(c.periode.tahun_akademik)} ${esc(c.periode.semester)}</small></span><span class="badge">${esc(apiStatus(c.status))}</span><span class="badge">${Number(c.jumlah_pertemuan_rencana)} pertemuan</span><span aria-hidden="true">↗</span></button>`).join('')||'<div class="empty">Belum ada kelas Praktikum yang dapat diakses.</div>'}</section>`;if(user.role==='admin'){$('#api-create-class').onclick=()=>apiClassForm();$('#api-import-schedule').onclick=importSchedule}document.querySelectorAll('[data-api-class]').forEach(b=>b.onclick=()=>apiClassDetail(Number(b.dataset.apiClass)))}catch(e){view.innerHTML=`<div class="error" role="alert">${esc(e.message)}</div>`}}
async function apiClassDetail(id){const view=$('#api-view');view.innerHTML='<div class="empty">Memuat detail kelas…</div>';try{const c=await api('/classes/'+id);apiCurrent=id;const schedules=c.jadwal||[],sessions=c.sesi||[],components=c.komponen_nilai||[],students=c.peserta||[];const weekday=['','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu'];view.innerHTML=`<div class="intro"><button class="small" id="api-back">← Kembali ke kelas</button><div class="eyebrow" style="margin-top:20px">${esc(c.mata_kuliah.kode)} · ${esc(c.program_studi.nama)} · ${esc(c.periode.tahun_akademik)} ${esc(c.periode.semester)}</div><h1>${esc(c.mata_kuliah.nama)}</h1><p>Kelompok ${esc(c.kelompok.kode)} · ${esc(apiStatus(c.status))} · ${Number(c.jumlah_pertemuan_rencana)} pertemuan direncanakan</p>${c.catatan?`<div class="warning">${esc(c.catatan)}</div>`:''}</div><section class="card"><div class="card-head"><h2>Jadwal dan penugasan</h2></div>${schedules.length?schedules.map(s=>`<div class="api-detail-row"><strong>${esc(weekday[Number(s.hari_ke)]||'Hari belum ditentukan')} · ${esc(String(s.jam_mulai||'').slice(0,5))}–${esc(String(s.jam_selesai||'').slice(0,5))}</strong><span>${esc(s.nama_laboratorium||s.nama_ruang||s.kode_ruang||'Ruang belum ditentukan')} · ${esc(apiStatus(s.status))}</span><small>${esc(s.tanggal_mulai||'—')} – ${esc(s.tanggal_selesai||'—')} · ${esc(apiStatus(s.pola_perulangan))} · Workflow ${esc(apiStatus(s.status_workflow))}</small><small>${(s.pengajar||[]).map(p=>`${esc(p.nama_peran||p.peran)}: ${esc(p.nama||'—')}`).join(' · ')||'Belum ada penugasan'}</small></div>`).join(''):'<div class="empty">Jadwal praktikum belum tersedia.</div>'}</section><section class="card"><div class="card-head"><h2>Sesi praktikum</h2></div>${sessions.length?`<div class="table-wrap"><table><thead><tr><th>PERTEMUAN</th><th>TANGGAL</th><th>TOPIK / MATERI</th><th>STATUS</th></tr></thead><tbody>${sessions.map(s=>`<tr><td>${Number(s.nomor_pertemuan)}</td><td>${esc(s.tanggal_sesi||'—')}</td><td>${esc([s.topik,s.materi].filter(Boolean).join(' · ')||'—')}</td><td>${esc(apiStatus(s.status))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada sesi yang tercatat.</div>'}</section><section class="card"><div class="card-head"><h2>Komponen penilaian</h2></div>${components.length?`<div class="table-wrap"><table><thead><tr><th>KODE</th><th>NAMA</th><th>BOBOT</th><th>STATUS</th></tr></thead><tbody>${components.map(x=>`<tr><td>${esc(x.kode)}</td><td>${esc(x.nama)}</td><td>${Number(x.bobot_persen)}%</td><td>${x.aktif?'Aktif':'Nonaktif'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Komponen nilai belum disiapkan.</div>'}</section>${Object.prototype.hasOwnProperty.call(c,'peserta')?`<section class="card"><div class="card-head"><h2>Peserta aktif · ${students.length}</h2></div>${students.length?`<div class="table-wrap"><table><thead><tr><th>NIM</th><th>NAMA</th><th>KEHADIRAN TERCATAT</th><th>NILAI TERCATAT</th></tr></thead><tbody>${students.map(s=>`<tr><td>${esc(s.nim)}</td><td>${esc(s.nama)}</td><td>${(s.kehadiran||[]).length}</td><td>${(s.nilai||[]).length}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Belum ada peserta aktif.</div>'}</section>`:`<section class="card"><div class="card-head"><h2>Ringkasan Anda</h2></div><div class="card-body"><p>Kehadiran tercatat: ${(c.kehadiran_saya||[]).length} · Komponen nilai tercatat: ${(c.nilai_saya||[]).length}</p><p>Detail nilai hanya memuat data akun Anda.</p></div></section>`}<p class="help">Mode API saat ini menyediakan pembacaan data. Perubahan absensi, nilai, jadwal, dan workflow akan diaktifkan setelah masing-masing form terhubung ke endpoint pusat.</p>`;$('#api-back').onclick=()=>{apiCurrent=null;apiClassList()}}catch(e){apiCurrent=null;view.innerHTML=`<div class="error" role="alert">${esc(e.message)}</div><button class="small" id="api-back">← Kembali</button>`;$('#api-back').onclick=apiClassList}}
async function apiStudentGrades(){const view=$('#api-view');view.innerHTML='<div class="empty">Memuat nilai dari API pusat…</div>';try{const rows=await api('/student/grades');if(!Array.isArray(rows))throw Error('Format nilai mahasiswa tidak valid.');const groups=new Map();for(const row of rows){const key=String(row.id_kelas_kuliah);if(!groups.has(key))groups.set(key,{first:row,summary:row.ringkasan_nilai,components:[]});if(row.kode_komponen)groups.get(key).components.push(row)}const fmt=value=>value===null||value===undefined?'—':Number(value).toFixed(2);view.innerHTML=`<div class="intro"><div class="eyebrow">PORTAL MAHASISWA / API PUSAT</div><h1>Nilai Saya</h1><p>Nilai akhir mengikuti rumus Praktikum yang berlaku; perhitungan dilakukan oleh API pusat.</p></div>${[...groups.values()].map(({first:r,summary:s,components})=>`<section class="card"><div class="card-head"><h2>${esc(r.kode_mata_kuliah)} · ${esc(r.nama_mata_kuliah)}</h2><p>${esc(r.semester)} ${esc(r.tahun_akademik)} · Kelompok ${esc(r.kode_kelompok)}</p></div><div class="card-body"><div class="stats"><div class="stat"><span class="label">Rata-rata Evaluasi</span><b>${fmt(s?.rata_evaluasi)}</b></div><div class="stat"><span class="label">Rata-rata Asistensi</span><b>${fmt(s?.rata_asistensi)}</b></div><div class="stat"><span class="label">Nilai Akhir</span><b>${fmt(s?.nilai_akhir)}</b><small>${s?.predikat?`Predikat ${esc(s.predikat)}`:s?.konfigurasi_nilai_tersedia?'Belum lengkap':'Konfigurasi nilai belum tersedia'}</small></div></div></div><div class="table-wrap"><table><thead><tr><th>KOMPONEN</th><th>NILAI</th><th>BOBOT</th></tr></thead><tbody>${components.map(c=>`<tr><td>${esc(c.nama_komponen||c.kode_komponen)}</td><td>${fmt(c.nilai)}</td><td>${c.bobot_persen===null?'—':Number(c.bobot_persen)+'%'}</td></tr>`).join('')||'<tr><td colspan="3">Belum ada komponen nilai.</td></tr>'}</tbody></table></div></section>`).join('')||'<section class="card"><div class="empty">Belum ada nilai praktikum.</div></section>'}`}catch(e){view.innerHTML=`<div class="error" role="alert">${esc(e.message)}</div>`}}
function hasUnsaved(){return changes.size||$('#meeting-date')?.dataset.dirty==='1'||$('#material')?.dataset.dirty==='1'||!!document.querySelector('#api-view [data-dirty="1"]')}
function navigate(p){if(hasUnsaved()&&!confirm('Perubahan belum disimpan. Tinggalkan halaman?'))return;changes.clear();current=null;page=p;render()}
function stats(){const students=classes.reduce((s,c)=>s+c.students,0),pending=classes.filter(c=>c.state==='Diajukan').length;return `<div class="stats">${[[classes.length,user.role==='dosen'?'Kelas yang diampu':'Kelas praktikum','▦','Semester berjalan'],[students,'Total mahasiswa','♙','Peserta di kelas Anda'],[classes.reduce((s,c)=>s+c.meetingCount,0),'Pertemuan tercatat','☑','Dari '+classes.reduce((n,c)=>n+c.meeting_count,0)+' pertemuan'],[pending,'Menunggu verifikasi','◈','Pengajuan kepada dosen']].map(([n,l,i,h])=>`<div class="stat"><div class="row between"><span class="label">${l}</span><span class="stat-icon">${i}</span></div><b>${n}</b><small>${h}</small></div>`).join('')}</div>`}
function dashboard(){const first=user.name.split(' ')[0],date=new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date());$('#view').innerHTML=`<div class="intro row between"><div><div class="eyebrow">RUANG KERJA / DASHBOARD</div><h1>Selamat datang, ${esc(first)} <span style="font-size:24px">☀</span></h1><p>Mari pantau kegiatan praktikum dan perkembangan mahasiswa Anda.</p></div><span class="badge" style="padding:10px 13px;background:white;border:1px solid #e6e8e2">◷ &nbsp; ${date}</span></div>${stats()}<div class="dashboard-grid"><div><section class="card"><div class="card-head row between"><div><h2>Jadwal praktikum Anda</h2><p>Kelola kehadiran dan penilaian dalam satu tempat.</p></div><button class="small" id="all-schedules">Lihat semua ↗</button></div>${classes.slice(0,4).map(schedule).join('')||'<div class="empty">Belum ada kelas yang ditugaskan.</div>'}</section><section class="card"><div class="card-head"><h2>Progres pengisian</h2><p>Pastikan semua data lengkap sebelum diajukan ke dosen.</p></div><div class="table-wrap"><table><thead><tr><th>MATA KULIAH</th><th>ABSENSI</th><th>PENILAIAN</th><th>STATUS</th></tr></thead><tbody>${classes.map(c=>`<tr><td><strong>${esc(c.course)}</strong><br><small>Frekuensi ${esc(c.class)} · ${esc(c.prodi)}</small></td><td>${progress(c.attendanceCount,c.students*c.meeting_count)}</td><td>${progress(c.gradeCount,c.students*(c.evaluation_count+c.assistance_count+2))}</td><td>${badge(c.state)}</td></tr>`).join('')}</tbody></table></div></section></div><aside class="dashboard-aside"><section class="card"><div class="card-head row between"><h2>Perlu perhatian</h2><span class="badge yellow">${classes.filter(c=>c.state==='Perlu Revisi'||c.gradeCount<c.students*(c.evaluation_count+c.assistance_count+2)||c.state==='Diajukan').length}</span></div><div class="card-body">${notifications()}</div></section><section class="dark-card"><small>PRAKTIKUM LEBIH TERATUR</small><h2 style="margin-top:16px">Setiap proses tercatat.<br>Setiap nilai bermakna.</h2><p>Periksa kembali absensi dan nilai sebelum menyelesaikan penilaian.</p><button class="primary small" id="open-report">Lihat rekap nilai ↗</button></section></aside></div><p class="footnote">ICLabs Praktikum · Laboratorium FIKOM UMI</p>`;bindOpen();$('#all-schedules').onclick=()=>navigate('Jadwal Praktikum');$('#open-report').onclick=()=>navigate('Laporan')}
function progress(n,d){const p=d?Math.round(n/d*100):0;return `${p}%<div class="progress"><i style="width:${p}%"></i></div>`}
function notifications(){return classes.map(c=>{const list=[];if(c.note&&c.state==='Perlu Revisi')list.push('Revisi dosen: '+c.note);if(user.role==='dosen'&&c.state==='Diajukan')list.push('Penilaian menunggu verifikasi Anda.');if(c.attendanceCount<c.students*c.meeting_count)list.push(`${c.students*c.meeting_count-c.attendanceCount} absensi belum diisi.`);if(c.lowGrades)list.push(`${c.lowGrades} mahasiswa dengan nilai akhir <55%.`);if(c.gradeCount<c.students*(c.evaluation_count+c.assistance_count+2))list.push(`${c.students*(c.evaluation_count+c.assistance_count+2)-c.gradeCount} nilai evaluasi, asistensi, atau ujian belum lengkap.`);if(c.lowPresence)list.push(`${c.lowPresence} mahasiswa dengan kehadiran <75%.`);return list.length?`<div class="notice"><strong><span class="dot"></span>${esc(c.course)} · ${esc(c.class)}</strong><p>${list.map(esc).join('<br>')}</p></div>`:''}).join('')||'<p>Semua pengisian sudah lengkap.</p>'}
function schedule(c){return `<div class="schedule"><div class="datebox">${esc(c.day.slice(0,3).toUpperCase())}<b>${esc(c.time.slice(0,5))}</b></div><div class="grow"><h3>${esc(c.course)}</h3><small>Frekuensi ${esc(c.class)} &nbsp;·&nbsp; ${esc(c.lab)} &nbsp;·&nbsp; ${esc(c.time)}${c.day===new Intl.DateTimeFormat('id-ID',{weekday:'long'}).format(new Date())?' &nbsp; <span class="badge yellow">Hari ini</span>':''}</small><div style="margin-top:8px"><small>${esc(c.lecturer)}</small></div></div>${badge(c.active?c.state:'Nonaktif')}<button class="small" data-open="${c.id}">Buka kelas ↗</button></div>`}
function bindOpen(){document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openClass(Number(b.dataset.open)))}
async function openClass(id){try{current=await api('/classes/'+id);meeting=1;changes.clear();tab=page==='Penilaian'?'Evaluasi':['Laporan','Verifikasi'].includes(page)?'Rekap Nilai':'Absensi';render()}catch(e){toast(e.message)}}
function listPage(){const isReport=page==='Laporan';$('#view').innerHTML=`<div class="intro"><div class="eyebrow">RUANG KERJA / ${esc(page.toUpperCase())}</div><h1>${page}</h1><p>${isReport?'Rekap kehadiran dan nilai, siap diunduh sesuai kelas praktikum.':'Pilih kelas praktikum untuk melihat dan mengelola data.'}</p></div><div class="filters"><input id="search" placeholder="⌕ Cari mata kuliah, kelas, dosen, atau asisten…"><select id="prodi"><option value="">Semua program studi</option><option>Teknik Informatika</option><option>Sistem Informasi</option></select><select id="year"><option value="">Semua tahun akademik</option>${[...new Set(classes.map(c=>c.year))].map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="semester"><option value="">Semua semester</option><option>Ganjil</option><option>Genap</option></select><select id="status"><option value="">Semua status</option>${['Draft','Diajukan','Perlu Revisi','Terverifikasi','Dikunci'].map(x=>`<option>${x}</option>`).join('')}</select></div><section class="card" id="class-list"></section>`;const update=()=>{const q=$('#search').value.toLowerCase();const rows=classes.filter(c=>(!$('#prodi').value||c.prodi===$('#prodi').value)&&(!$('#year').value||c.year===$('#year').value)&&(!$('#semester').value||c.semester===$('#semester').value)&&(!$('#status').value||c.state===$('#status').value)&&[c.course,c.code,c.class,c.frequency,c.lecturer,c.assistant1,c.assistant2].join(' ').toLowerCase().includes(q));$('#class-list').innerHTML=rows.map(schedule).join('')||'<div class="empty">Tidak ada kelas yang cocok dengan filter.</div>';bindOpen()};$('.filters').oninput=update;update()}
function canEdit(){return ['admin','asisten'].includes(user.role)&&current.class.active&&['Draft','Perlu Revisi'].includes(current.class.state)}
function renderClass(){const c=current.class;$('#view').innerHTML=`<div class="intro"><button class="small" id="back">← Kembali ke ${esc(page)}</button><div class="row between" style="margin-top:24px"><div><div class="eyebrow">${esc(c.code)} · ${esc(c.prodi)} · ${esc(c.year)} ${esc(c.semester)}</div><h1>${esc(c.course)}</h1><p>Frekuensi ${esc(c.class)} &nbsp; / &nbsp; ${esc(c.day)}, ${esc(c.time)} &nbsp; / &nbsp; ${esc(c.lab)} &nbsp; / &nbsp; ${c.sks} SKS</p></div>${badge(c.state)}</div></div>${c.note?`<div class="warning"><strong>Catatan verifikasi:</strong> ${esc(c.note)}</div>`:''}<section class="card"><div class="card-body summary-meta"><div><small>FREKUENSI</small>${esc(c.frequency||'—')}</div><div><small>DOSEN PENGAMPU</small>${esc(c.lecturer)}</div><div><small>ASISTEN PRAKTIKUM</small>${esc(c.assistant1)} · ${esc(c.assistant2)}</div><div><small>PESERTA</small>${current.students.length} mahasiswa <span class="muted">/ ${c.active?'Jadwal aktif':'Nonaktif'}</span></div></div><div class="tabs">${['Absensi','Evaluasi','Asistensi','MID','UAS','Rekap Nilai','Riwayat'].map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}">${t}</button>`).join('')}</div><div class="card-body row between"><small>${c.meeting_count} pertemuan · ${c.evaluation_count} evaluasi · ${c.assistance_count} asistensi</small>${canEdit()?'<button class="small" id="components">Atur jumlah pengisian</button>':''}</div><div id="class-content"></div><div class="savebar row between"><small id="save-status">Semua perubahan tersimpan · versi ${c.version}</small><div class="row" id="class-actions">${canEdit()?'<button class="primary" id="save">Simpan perubahan</button>':''}${workflowButtons()}</div></div></section>`;$('#back').onclick=()=>navigate(page);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(hasUnsaved()){toast('Simpan perubahan sebelum berpindah tab.');return}tab=b.dataset.tab;classContent()});if($('#components'))$('#components').onclick=configureComponents;if($('#save'))$('#save').onclick=save;document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>workflow(b.dataset.state));classContent()}
function workflowButtons(){const c=current.class;return `${canEdit()?'<button id="submit" data-state="Diajukan">Ajukan ke dosen ↗</button>':''}${user.role==='dosen'&&c.state==='Diajukan'?'<button data-state="Perlu Revisi">Minta revisi</button><button class="primary" data-state="Terverifikasi">Verifikasi nilai</button>':''}${user.role==='dosen'&&c.state==='Terverifikasi'?'<button class="dark" data-state="Dikunci">Kunci penilaian</button>':''}${user.role==='admin'&&['Terverifikasi','Dikunci','Diajukan'].includes(c.state)?'<button data-state="Draft">Buka kembali</button>':''}`}
function field(s,kind,n,value){const key=`${s.id}-${kind}-${n}`,v=changes.has(key)?changes.get(key).value:value;return `<input type="number" min="0" max="100" step="0.01" data-student="${s.id}" data-kind="${kind}" data-number="${n}" value="${esc(v??'')}" ${canEdit()?'':'disabled'} aria-label="${esc(s.name)} ${kind} ${n}">`}
function classContent(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));const d=current,c=d.class,students=d.students;let html='';if(tab==='Absensi'){const m=d.meetings.find(m=>m.number===meeting);html=`<div class="card-body row"><label>Pertemuan<select id="meeting">${Array.from({length:current.class.meeting_count},(_,i)=>`<option value="${i+1}" ${meeting===i+1?'selected':''}>Pertemuan ${i+1}</option>`).join('')}</select></label><label>Tanggal<input type="date" id="meeting-date" value="${esc(m?.date||new Date().toISOString().slice(0,10))}" ${canEdit()?'':'disabled'}></label><label style="flex:1;min-width:190px">Materi praktikum<input id="material" placeholder="Tuliskan materi pertemuan…" value="${esc(m?.material||'')}" ${canEdit()?'':'disabled'}></label>${canEdit()?'<button id="all-present" style="align-self:end">✓ Hadirkan semua</button>':''}</div><div class="table-wrap"><table><thead><tr><th>NO</th><th class="name">MAHASISWA</th><th>STATUS KEHADIRAN</th><th>CATATAN</th><th>REKAP HADIR</th></tr></thead><tbody>${students.map((s,i)=>{const v=changes.get(`${s.id}-attendance-${meeting}`)||s.attendance.find(a=>a.number===meeting);return `<tr><td>${i+1}</td><td class="name"><strong>${esc(s.name)}</strong><small>${s.nim}</small></td><td><select data-student="${s.id}" data-kind="attendance" data-number="${meeting}" ${canEdit()?'':'disabled'}><option value="">Belum diisi</option>${[['H','H · Hadir'],['I','I · Izin'],['S','S · Sakit'],['A','A · Alpa'],['T','T · Terlambat']].map(([k,l])=>`<option value="${k}" ${v?.value===k?'selected':''}>${l}</option>`).join('')}</select></td><td><input class="note" data-note="${s.id}" value="${esc(v?.note||'')}" placeholder="Catatan opsional" ${canEdit()?'':'disabled'}></td><td>${badge(num(s.presence)+'%')} <small>${s.attendance.filter(a=>a.value==='H').length}/${d.meetings.length} hadir</small></td></tr>`}).join('')}</tbody></table></div><div class="help">H = Hadir · I = Izin · S = Sakit · A = Alpa · T = Terlambat. Kehadiran dihitung dari status H dan pertemuan yang tercatat.</div>`}
else if(['Evaluasi','Asistensi','MID','UAS'].includes(tab)){const n=tab==='Evaluasi'?c.evaluation_count:tab==='Asistensi'?c.assistance_count:1,kind=tab==='Evaluasi'?'evaluation':tab==='Asistensi'?'assistance':tab;html=`<div class="card-body row between"><div><h3 style="margin-bottom:6px">Nilai ${tab}</h3><small>Rentang 0–100. Kolom kosong berarti belum dinilai; nilai 0 tetap dihitung.</small></div>${canEdit()&&['Evaluasi','Asistensi'].includes(tab)?`<button class="small" id="add-component">+ Tambah ${tab}</button>`:''}<span class="badge yellow">Bobot ${['MID','UAS'].includes(tab)?'30%':'20%'}</span></div><div class="table-wrap"><table><thead><tr><th>NO</th><th class="name">MAHASISWA</th>${Array.from({length:n},(_,i)=>`<th>${tab.toUpperCase()} ${!['MID','UAS'].includes(tab)?i+1:''}</th>`).join('')}${!['MID','UAS'].includes(tab)?'<th>RATA-RATA</th>':''}</tr></thead><tbody>${students.map((s,i)=>`<tr><td>${i+1}</td><td class="name"><strong>${esc(s.name)}</strong><small>${s.nim}</small></td>${Array.from({length:n},(_,j)=>`<td>${field(s,kind,j+1,['MID','UAS'].includes(tab)?s[tab.toLowerCase()]:(tab==='Evaluasi'?s.evaluations:s.assistance).find(x=>x.number===j+1)?.value)}</td>`).join('')}${!['MID','UAS'].includes(tab)?`<td><strong>${num(tab==='Evaluasi'?s.ev:s.as)}</strong></td>`:''}</tr>`).join('')}</tbody></table></div>`}
else if(tab==='Rekap Nilai'){html=`<div class="card-body row between"><div><h3 style="margin-bottom:6px">Rekap kehadiran & nilai akhir</h3><small>Evaluasi 20% + Asistensi 20% + MID 30% + UAS 30%</small></div><div class="row"><button class="small" data-export="xlsx">↓ Excel</button><button class="small" data-export="pdf">↓ PDF</button><button class="small" id="print">⌑ Print</button></div></div><div class="table-wrap"><table><thead><tr><th>NO</th><th class="name">MAHASISWA</th><th>H / I / S / A / T</th><th>KEHADIRAN</th><th>EVALUASI</th><th>ASISTENSI</th><th>MID</th><th>UAS</th><th>NA</th><th>HURUF</th><th>STATUS</th></tr></thead><tbody>${students.map((s,i)=>`<tr><td>${i+1}</td><td class="name"><button class="small" data-detail="${s.id}">${esc(s.name)}</button><small>${s.nim}</small></td><td>${['H','I','S','A','T'].map(v=>s.attendance.filter(a=>a.value===v).length).join(' / ')}</td><td><span class="badge ${s.presence<75?'red':'green'}">${num(s.presence)}%</span></td><td>${num(s.ev)}</td><td>${num(s.as)}</td><td>${num(s.mid)}</td><td>${num(s.uas)}</td><td><strong>${num(s.na)}</strong></td><td>${badge(s.letter)}</td><td>${badge(c.state)}</td></tr>`).join('')}</tbody></table></div><div class="help">Klik nama mahasiswa untuk melihat detail dan riwayat input. Nilai akhir belum tersedia jika salah satu komponen belum dinilai.</div>`}
else html=auditTable(d.history);
$('#class-content').innerHTML=html;if($('#add-component'))$('#add-component').onclick=()=>addComponent();if(!students.length&&tab!=='Riwayat')$('#class-content').insertAdjacentHTML('beforeend','<div class="empty">Belum ada peserta. Admin dapat menyinkronkan mahasiswa dari Data Master.</div>');
document.querySelectorAll('[data-kind]').forEach(el=>el.onchange=()=>{const s=Number(el.dataset.student),kind=el.dataset.kind,n=Number(el.dataset.number);if(kind!=='attendance'&&!el.checkValidity()){el.reportValidity();return}if(kind==='attendance'&&!el.value){toast('Pilih status H, I, S, A, atau T.');return}changes.set(`${s}-${kind}-${n}`,{student:s,kind,number:n,value:kind==='attendance'?el.value:el.value===''?null:Number(el.value),...(kind==='attendance'?{note:document.querySelector(`[data-note="${s}"]`).value}:{})});dirty()});
document.querySelectorAll('[data-note]').forEach(el=>el.onchange=()=>{const select=document.querySelector(`[data-student="${el.dataset.note}"]`);select.onchange()});if($('#meeting')){$('#meeting').onchange=e=>{if(hasUnsaved()){e.target.value=meeting;toast('Simpan perubahan sebelum berpindah pertemuan.');return}meeting=Number(e.target.value);classContent()};for(const id of ['#material','#meeting-date'])$(id).oninput=()=>{$(id).dataset.dirty='1';dirty()};if($('#all-present'))$('#all-present').onclick=()=>{document.querySelectorAll('[data-kind="attendance"]').forEach(el=>{el.value='H';el.onchange()})}}
document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>download(b.dataset.export));if($('#print'))$('#print').onclick=()=>window.print();document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>studentDetail(Number(b.dataset.detail)))}
function dirty(){$('#save-status').textContent=`● Perubahan belum disimpan (${changes.size} data)`;$('#save-status').style.color='#a68719'}
async function save(){try{if(document.querySelector('input:invalid')){document.querySelector('input:invalid').reportValidity();return}const b={version:current.class.version,changes:[...changes.values()]};if(tab==='Absensi')b.meeting={number:meeting,date:$('#meeting-date').value,material:$('#material').value};await api('/classes/'+current.class.id+'/save',b);changes.clear();current=await api('/classes/'+current.class.id);classes=await api('/classes');renderClass();toast('Perubahan berhasil disimpan.')}catch(e){toast(e.message)}}
function dialog(html){const m=$('#modal');m.innerHTML=html;m.showModal();m.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>m.close());return m}
function workflow(state){if(hasUnsaved()){toast('Simpan perubahan sebelum mengubah status.');return}const m=dialog(`<form><h2>${esc(state==='Draft'?'Buka kembali penilaian':state)}</h2><p>Perubahan status berlaku untuk seluruh peserta kelas ${esc(current.class.class)}.</p><label>Catatan / alasan<textarea name="note" rows="3" ${['Draft','Perlu Revisi'].includes(state)?'required':''}></textarea></label><div class="row"><button type="button" data-close>Batal</button><button class="primary">Konfirmasi ${esc(state)}</button></div></form>`);m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/classes/'+current.class.id+'/workflow',{state,note:new FormData(e.target).get('note'),version:current.class.version});m.close();current=await api('/classes/'+current.class.id);classes=await api('/classes');renderClass();toast('Status penilaian diperbarui.')}catch(x){toast(x.message)}}}
async function download(format){try{const r=await fetch(apiUrl(`/classes/${current.class.id}/export?format=${format}`));if(!r.ok)throw Error((await r.json()).error);const u=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=u;a.download=`Praktikum-${current.class.code}-${current.class.class}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(u),5000)}catch(e){toast(e.message)}}
function auditTable(rows){return `<div class="table-wrap"><table><thead><tr><th>WAKTU</th><th>PENGGUNA</th><th>PERUBAHAN</th><th>SEBELUM</th><th>SESUDAH</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${new Date(r.created_at).toLocaleString('id-ID')}</td><td>${esc(r.name)}<br><small>${esc(roleLabel[r.role]||({asisten1:'Asisten (posisi lama 1)',asisten2:'Asisten (posisi lama 2)'})[r.role]||r.role)}</small></td><td>${esc(r.entity)}</td><td class="audit">${esc(r.old_value)}</td><td class="audit">${esc(r.new_value)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">Belum ada perubahan data.</div>'}</div>`}
function studentDetail(id){const s=current.students.find(s=>s.id===id);dialog(`<div class="row between"><h2>${esc(s.name)}</h2><button data-close>Tutup</button></div><p>${s.nim} · Frekuensi ${esc(current.class.class)}</p><div class="student-detail"><div><strong>Absensi 1–${current.class.meeting_count}</strong><br>${Array.from({length:current.class.meeting_count},(_,i)=>`${i+1}: ${s.attendance.find(a=>a.number===i+1)?.value||'—'}`).join(' · ')}</div><div><strong>Evaluasi 1–${current.class.evaluation_count}</strong><br>${Array.from({length:current.class.evaluation_count},(_,i)=>`${i+1}: ${s.evaluations.find(a=>a.number===i+1)?.value??'—'}`).join(' · ')}</div><div><strong>Asistensi 1–${current.class.assistance_count}</strong><br>${Array.from({length:current.class.assistance_count},(_,i)=>`${i+1}: ${s.assistance.find(a=>a.number===i+1)?.value??'—'}`).join(' · ')}</div><div><strong>Ujian & nilai akhir</strong><br>MID ${num(s.mid)} · UAS ${num(s.uas)}<br>NA ${num(s.na)} (${s.letter})</div></div><h3 style="margin-top:25px">Riwayat input mahasiswa</h3>${auditTable(current.history.filter(r=>r.entity.startsWith(id+':')))}`)}
async function logout(){
  if(hasUnsaved()&&!confirm('Ada perubahan belum disimpan. Tetap logout?'))return;
  const buttons=[$('#logout'),$('#header-logout')].filter(Boolean);
  buttons.forEach(b=>b.disabled=true);
  try{
    await api('/logout',{});
    current=null;classes=[];masterData=null;changes.clear();page='Dashboard';tab='Absensi';meeting=1;
    if($('#modal').open)$('#modal').close();
    login();toast('Anda berhasil logout.');
  }catch(e){buttons.forEach(b=>b.disabled=false);toast(e.message)}
}
function account(){const m=dialog('<form><h2>Ganti password</h2><label>Password saat ini<input name="current" type="password" required autocomplete="current-password"></label><label>Password baru (minimal 12 karakter)<input name="password" type="password" minlength="12" required autocomplete="new-password"></label><div class="row"><button type="button" data-close>Batal</button><button class="primary">Simpan password</button></div></form>');m.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/password',Object.fromEntries(new FormData(e.target)));m.close();toast('Password diperbarui.')}catch(x){toast(x.message)}}}
